package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;
@RunWith(AndroidJUnit4.class) public class Android0515Test {
 final Android050FlowTest f=new Android050FlowTest();
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{f.app.connectionDraft.close();f.app.forgetConnection();f.app.cancelScan();f.app.epoch++;});f.cleanup();UiLocale.save(f.context,"hu");}
 void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+15000;while(!condition.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Operation did not finish",condition.getAsBoolean());}
 void setup(FakeNas nas)throws Exception{f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.recovery.reset();f.app.checkNetwork();});f.setup(nas,List.of(new Library.Card("/Movies/Demo.Movie.2020.mkv","Fixture",true)));}
 void fillPassword(){f.device.findObject(By.res(f.pkg+":id/login_password")).setText("fixture-password");}
 @Test public void corruptProfileRequiresConsentAfterRotationAndKeepsRecoveredIdUntilLogin()throws Exception{try(FakeNas nas=new FakeNas()){
  setup(nas);String old=AccountIdentity.owner(nas.address(),"fixture-user");f.app.store.put("address",nas.address());f.app.store.put("local","");f.app.store.put("ddns","");f.app.store.put("quick","");f.app.store.put("user","fixture-user");f.app.store.put("libraries_owner",old);f.app.store.put("nas_profile","{broken");f.app.store.put("edits:"+old,"old-edits-fixture");f.click("menu_button");f.text("Kijelentkezés");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_address")),5000));fillPassword();int before=nas.authLogins;f.click("login_button");
  assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message").textContains("korábbi kézi javítások")),5000));assertTrue("Igen".equalsIgnoreCase(f.device.findObject(By.res("android:id/button1")).getText()));assertTrue("Nem".equalsIgnoreCase(f.device.findObject(By.res("android:id/button2")).getText()));f.device.findObject(By.res("android:id/button2")).click();assertEquals("{broken",f.app.store.get("nas_profile",""));assertEquals("",f.app.store.get("nas_profile_recovery",""));assertEquals(before,nas.authLogins);
  f.device.setOrientationLeft();f.device.setOrientationNatural();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_password")),10000));fillPassword();f.click("login_button");assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message").textContains("korábbi kézi javítások")),5000));nas.rejectNewLogins=true;f.device.findObject(By.res("android:id/button1")).click();waitFor(()->!f.app.busy&&nas.authLogins>before);
  assertFalse(f.context.getSharedPreferences("synostream",android.content.Context.MODE_PRIVATE).contains("nas_profile"));String recovered=NasProfile.load(f.app.store).id;assertEquals(recovered,NasProfile.load(f.app.store).id);assertEquals(0,NasProfile.load(f.app.store).json("").getJSONObject("owners").length());assertEquals("old-edits-fixture",f.app.store.get("edits:"+old,""));nas.rejectNewLogins=false;fillPassword();f.click("login_button");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/poster_grid")),15000));waitFor(()->!f.app.busy&&!f.app.scanRunning);assertEquals(recovered,NasProfile.load(f.app.store).id);assertEquals("",f.app.store.get("nas_profile_recovery",""));assertNotEquals(old,f.app.identity);assertEquals("old-edits-fixture",f.app.store.get("edits:"+old,""));
 }}
 @Test public void codeRequiredResultIsLocalisedWithoutBreakingActiveClient()throws Exception{try(FakeNas nas=new FakeNas()){
  setup(nas);NasClient root=f.app.client;nas.rejectNewLogins=true;MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->ConnectionSettingsUi.check(a,root.settingsCredentials()));assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message").textContains("Elérhető; a bejelentkezéshez kétlépcsős kód kell")),15000));assertSame(root,f.app.client);f.instrumentation.runOnMainSync(()->assertTrue(f.app.connectionReady()));f.device.findObject(By.res("android:id/button1")).click();assertArrayEquals(new byte[]{0,1,2,3},root.readFile("/Movies/Demo.Movie.2020.mkv",100));UiLocale.save(f.context,"en");f.instrumentation.runOnMainSync(a::recreate);assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/connection_toolbar").textStartsWith("Connection:")),10000));MainActivity english=f.activity();f.instrumentation.runOnMainSync(()->ConnectionSettingsUi.check(english,root.settingsCredentials()));assertTrue(f.device.wait(Until.hasObject(By.res("android:id/message").textContains("Reachable; a two-step code is required to sign in")),15000));f.device.findObject(By.res("android:id/button1")).click();assertSame(root,f.app.client);
 }}
}
